dle_AC() {}		// Releases the thread. 	CThread_AC* GetThread() const { return get(); }		// Accesses the context.};//========================================================================================// CThreadRunner_AC//========================================================================================class EXPORT_AC CThreadRunner_AC : public CThreadHandle_AC// CThreadRunner_AC is the class used to launch and interact with the state of a thread// or MP task.  Multiple handles may be associated with a single executing thread, and// reference counting is used to ensure that valid information about the thread state is// available to any outstanding handles, even after the thread has terminated.//// Construct a CThreadRunner_AC using a new object of a subclass of CThread_AC // to start a new thread of execution.  The CThread_AC object will be deleted// when the thread is no longer executing and all CThreadRunners_AC referencing it have // been destructed.//// To cooperatively terminate a running thread, call RequestShutdown.  To synchronize on // the termination of the thread, call Join.{public:	CThreadRunner_AC(CThread_AC* aThread = NULL);		// Constructor. Starts the thread. 	~CThreadRunner_AC();		// Destructor waits for the thread to finish and releases it. 	CThreadRunner_AC& operator=(CThread_AC* aThread)		{ reset(aThread); return *this; }	CThreadRunner_AC& operator=(CThreadRunner_AC& aThread)	{ reset(aThread); return *this; }		// Assignment. Acquires and starts the thread. 	void reset(CThread_AC* aThread = NULL);		// Releases the old pointee and aquires and starts the new one if any. };//========================================================================================// CThreadExceptionHandler_AC//========================================================================================class EXPORT_AC CThreadExceptionHandler_AC// A CThreadExceptionHandler is installed to handle thread exceptions that propagate to// the thread prologue (where aThread->Run() is called).  Frameworks should install// an exception handler that can post a command or action in the main thread which can// notify the user that the task has terminated unexpectedly. {public:	CThreadExceptionHandler_AC();		// constructor			virtual ~CThreadExceptionHandler_AC();		// destructor		//--------------------------------------------------------------------------------	// Exception handler methods to override	//--------------------------------------------------------------------------------	virtual void HandleException(CException_AC& theException);		// Handle an exception.  Should post a command or action in the main thread		// which can notify the user that "A task has unexpectedly terminated."		virtual void HandleException();		// Handle an unspecified exception.  Should post a command or action in the main thread		// which can notify the user that "A task has unexpectedly terminated."		//--------------------------------------------------------------------------------	// Installing and retrieving the installed exception handler	//--------------------------------------------------------------------------------	static void CallHandleException(CException_AC& theException);		// Handle an exception.  Redirects to instance.		static void CallHandleException();		// Handle an unspecified exception. Redirects to instance.			static CThreadExceptionHandler_AC* Instance() { return fgInstance; }		// Returns the installed exception handler, if any.protected:	static CAutoPtr_AC<CThreadExceptionHandler_AC> fgInstance;		// Returns the installed thread exception handler.};#endif	// __CThreadRunner_AC__